import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom fused ConvTranspose3d + ReLU kernel
conv_relu_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_conv_transpose_relu_kernel(
    const float* input, const float* weight,
    float* output,
    int B, int IC, int OC,
    int ID, int IH, int IW,
    int OD, int OH, int OW
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = B * OC * OD * OH * OW;
    if (idx >= total) return;

    int b = idx / (OC * OD * OH * OW);
    int oc = (idx / (OD * OH * OW)) % OC;
    int od = (idx / (OH * OW)) % OD;
    int oh = (idx / OW) % OH;
    int ow = idx % OW;

    float sum = 0.0f;

    for (int ic = 0; ic < IC; ic++) {
        for (int kd = 0; kd < 3; kd++) {
            for (int kh = 0; kh < 3; kh++) {
                for (int kw = 0; kw < 3; kw++) {
                    int id = od - kd;
                    int ih = oh - kh;
                    int iw = ow - kw;
                    if (id >= 0 && id < ID && ih >= 0 && ih < IH && iw >= 0 && iw < IW) {
                        int inp_idx = ((b * IC + ic) * ID + id) * IH * IW + ih * IW + iw;
                        int w_idx = ((oc * IC + ic) * 3 + kd) * 3 * 3 + kh * 3 + kw;
                        sum += input[inp_idx] * weight[w_idx];
                    }
                }
            }
        }
    }
    output[idx] = fmaxf(sum, 0.0f);
}

torch::Tensor fused_conv_transpose_relu_cuda(
    torch::Tensor input, torch::Tensor weight,
    int OD, int OH, int OW
) {
    int B = input.size(0);
    int IC = input.size(1);
    int ID = input.size(2);
    int IH = input.size(3);
    int IW = input.size(4);
    int OC = weight.size(0);

    auto output = torch::empty({B, OC, OD, OH, OW}, input.options());

    int total = B * OC * OD * OH * OW;
    int threads = 256;
    int blocks = (total + threads - 1) / threads;

    fused_conv_transpose_relu_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(), weight.data_ptr<float>(),
        output.data_ptr<float>(),
        B, IC, OC,
        ID, IH, IW,
        OD, OH, OW
    );

    return output;
}
"""

# Custom GroupNorm kernel
group_norm_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void group_norm_kernel(
    const float* input, float* output,
    const float* gamma, const float* beta,
    int B, int C, int G,
    int D, int H, int W,
    int GS,
    float eps
) {
    int group = blockIdx.x;
    int c_start = group * GS;
    int c_end = c_start + GS;

    extern __shared__ float smem[];
    float* sum = smem;
    float* sum_sq = smem + 1;

    if (threadIdx.x == 0) {
        sum[0] = 0.0f;
        sum_sq[0] = 0.0f;
    }
    __syncthreads();

    for (int b = 0; b < B; b++) {
        for (int c = c_start; c < c_end; c++) {
            for (int d = 0; d < D; d++) {
                for (int h = 0; h < H; h++) {
                    for (int w = 0; w < W; w++) {
                        int idx = ((b * C + c) * D + d) * H * W + h * W + w;
                        float val = input[idx];
                        atomicAdd(sum, val);
                        atomicAdd(sum_sq, val * val);
                    }
                }
            }
        }
    }
    __syncthreads();

    float mean = sum[0] / (B * GS * D * H * W);
    float var = (sum_sq[0] / (B * GS * D * H * W)) - (mean * mean);

    for (int b = 0; b < B; b++) {
        for (int c = c_start; c < c_end; c++) {
            for (int d = 0; d < D; d++) {
                for (int h = 0; h < H; h++) {
                    for (int w = 0; w < W; w++) {
                        int idx = ((b * C + c) * D + d) * H * W + h * W + w;
                        float val = input[idx];
                        output[idx] = (val - mean) / sqrtf(var + eps) * gamma[c] + beta[c];
                    }
                }
            }
        }
    }
}

torch::Tensor group_norm_cuda(
    torch::Tensor input, torch::Tensor gamma, torch::Tensor beta,
    int G, float eps
) {
    int B = input.size(0);
    int C = input.size(1);
    int D = input.size(2);
    int H = input.size(3);
    int W = input.size(4);
    int GS = C / G;

    auto output = torch::empty_like(input);

    dim3 blocks(G);
    dim3 threads(1);
    size_t smem = 2 * sizeof(float);

    group_norm_kernel<<<blocks, threads, smem>>>(
        input.data_ptr<float>(), output.data_ptr<float>(),
        gamma.data_ptr<float>(), beta.data_ptr<float>(),
        B, C, G,
        D, H, W,
        GS,
        eps
    );

    return output;
}
"""

# Load inline CUDA extensions
custom_ops = load_inline(
    name='custom_ops',
    cpp_sources='',
    cuda_sources=conv_relu_source + group_norm_source,
    functions=[
        'fused_conv_transpose_relu_cuda',
        'group_norm_cuda'
    ],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, groups, bias=False):
        super(ModelNew, self).__init__()
        self.groups = groups
        self.eps = 1e-5

        # ConvTranspose parameters
        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels, 3, 3, 3)
        )
        nn.init.kaiming_normal_(self.weight, mode='fan_out', nonlinearity='relu')

        # GroupNorm parameters
        self.gamma = nn.Parameter(torch.ones(out_channels))
        self.beta = nn.Parameter(torch.zeros(out_channels))

    def forward(self, x):
        # Calculate output shape
        _, _, D_in, H_in, W_in = x.shape
        D_out = D_in + 2
        H_out = H_in + 2
        W_out = W_in + 2

        # Fused ConvTranspose + ReLU
        x = custom_ops.fused_conv_transpose_relu_cuda(
            x, self.weight,
            D_out, H_out, W_out
        )

        # Custom GroupNorm
        x = custom_ops.group_norm_cuda(
            x, self.gamma, self.beta,
            self.groups, self.eps
        )

        return x
